const (
	// SessionStateDirName is the directory name for session state files within git common dir.
	SessionStateDirName = "entire-sessions"

	// StaleSessionThreshold is the duration after which an ended session is considered stale
	// and will be automatically deleted during load/list operations.
	StaleSessionThreshold = 7 * 24 * time.Hour

	// StuckActiveThreshold is the duration after which an ACTIVE session with no
	// interaction is considered stuck (used by "entire doctor" and "entire status").
	StuckActiveThreshold = 1 * time.Hour
)

// Kind identifies the purpose of a session. Empty means "normal" (legacy
// extraction, via direct field mutation on the claimed record within the
// same MutateSessionState closure that called CompleteTaskRecord — see
// strategy.CompleteTaskRecord, the producer-facing wrapper that pairs the
// claim with the attach inside one lock.
func (s *State) CompleteTaskRecord(toolUseID string, completedAt time.Time) bool {
	for i := range s.TaskRecords {
		if s.TaskRecords[i].ToolUseID != toolUseID {
			continue
		}
		if !s.TaskRecords[i].CompletedAt.IsZero() {
			return false
		}
		s.TaskRecords[i].CompletedAt = completedAt
		return true
	}
	return false
}

// HasTaskContent reports whether this session carries pending subagent task
// content: any task record — live (transcript-so-far still needs capturing)
// or completed-unmaterialized (awaiting condensation) — counts.
func (s *State) HasTaskContent() bool {
	return len(s.TaskRecords) > 0
}

// HasPendingWork reports whether this session holds work no checkpoint has
// captured yet: a turn-end step since the last condensation (StepCount), files
// still awaiting a commit (FilesTouched, including carry-forward), or subagent
// task records.
//
// It is the single answer to "is there anything here to condense or lose?" —
// lifecycle cleanup, doctor, the session sweeper, and condensation all ask it,
// and must not re-derive it from the parts. (Shadow-branch existence used to
// stand in for it; nothing writes git objects at turn end anymore.)
//
// It deliberately ignores FullyCondensed: a fully condensed session can still
// carry task records (a background subagent finishing after its session
// ended). Callers that must leave fully condensed sessions alone — doctor's
// ENDED classification, the zombie sweep, IsCondensableEndedSession — check
// FullyCondensed themselves, as they always have.
func (s *State) HasPendingWork() bool {
	return s.StepCount > 0 || s.HasPendingFiles() || s.HasTaskContent()
}

// HasPendingFiles reports whether files await a commit in any worktree: the
// home's FilesTouched or any OtherWorktrees entry's.
func (s *State) HasPendingFiles() bool {
	if len(s.FilesTouched) > 0 {
		return true
	}
	for _, work := range s.OtherWorktrees {
		if work != nil && len(work.FilesTouched) > 0 {
			return true
		}
	}
	return false
}

// PendingFileCount is the number of files awaiting a commit across every
// worktree: len(PendingFiles()).
func (s *State) PendingFileCount() int {
	return len(s.PendingFiles())
}

// PendingFiles is the repository paths awaiting a commit across every
// worktree (see HasPendingFiles), sorted. A path pending in two worktrees is
// listed once: a checkpoint records the paths it touched, as a set of
// repository paths, not per worktree.
func (s *State) PendingFiles() []string {
